import { useState, useEffect } from "react";

/* ── Bengali helpers ── */
const BN = ["০","১","২","৩","৪","৫","৬","৭","৮","৯"];
const toBn = (n) => String(n).replace(/[0-9]/g, d => BN[+d]);
const toEn = (s) => String(s).replace(/[০-৯]/g, d => BN.indexOf(d));
const BN_MONTHS = ["জানুয়ারি","ফেব্রুয়ারি","মার্চ","এপ্রিল","মে","জুন","জুলাই","আগস্ট","সেপ্টেম্বর","অক্টোবর","নভেম্বর","ডিসেম্বর"];
const fmtDate = (s) => {
  if (!s) return "";
  const [y,m,d] = s.split("-");
  return `${toBn(parseInt(d))} ${BN_MONTHS[+m-1]} ${toBn(y)}`;
};
const todayStr = () => new Date().toISOString().split("T")[0];

/* ── 12 Stations from actual document ── */
const STATIONS = [
  { id:1,  name:"জীবননগর ফিলিং স্টেশন জীবননগর, চুয়াডাঙ্গা" },
  { id:2,  name:"নাসিম ফিলিং স্টেশন, দত্তনগর রোড, জীবননগর, চুয়াডাঙ্গা" },
  { id:3,  name:"পিয়াস ফিলিং স্টেশন, দেহাটি জীবননগর, চুয়াডাঙ্গা" },
  { id:4,  name:"উৎসব ফিলিং স্টেশন, লক্ষীপুর জীবননগর, চুয়াডাঙ্গা" },
  { id:5,  name:"অংগন ফিলিং স্টেশন, সন্তোষপুর জীবননগর, চুয়াডাঙ্গা" },
  { id:6,  name:"মেসার্স লিমা ফিলিং স্টেশন, হাসাদাহ জীবননগর" },
  { id:7,  name:"মেসার্স এ এম এন্ড সন্স উথলী বাসস্ট্যান্ড, জীবননগর" },
  { id:8,  name:"মেসার্স এম.পিএল ট্রেডার্স হাসাদাহ" },
  { id:9,  name:"মেসার্স মওলা ট্রেডার্স হাসাদাহ জনাব মোঃ ইয়াছীন আলী" },
  { id:10, name:"মেসার্স আব্দুস সাত্তার জীবননগর বাজার" },
  { id:11, name:"মেসার্স আব্দুল আলিম জীবননগর বাজার" },
  { id:12, name:"মেসার্স মোস্তফা অটোমোবাইলস, জীবননগর বাজার" },
];
const FUELS     = ["diesel","petrol","octane"];
const FUEL_LBL  = { diesel:"ডিজেল", petrol:"পেট্রোল", octane:"অকটেন" };
const FIELDS    = ["prev","received","closing"];
const FIELD_LBL = { prev:"পূর্বের মজুদ(লিঃ)", received:"ডিপো হতে গ্রহণ (লিঃ)", closing:"সমাপনী মজুদ(লিঃ)" };

const emptyRow  = () => ({ diesel:{prev:"",received:"",closing:""}, petrol:{prev:"",received:"",closing:""}, octane:{prev:"",received:"",closing:""} });
const emptyData = () => STATIONS.map(s => ({ stationId:s.id, ...emptyRow() }));

const STORE_KEY = "fuel_report_v3";
const loadAll   = async () => { try { const r = await window.storage.get(STORE_KEY); return r ? JSON.parse(r.value) : {}; } catch { return {}; } };
const saveAll   = async (d) => { try { await window.storage.set(STORE_KEY, JSON.stringify(d)); } catch(e) { console.error(e); } };

const calcTotal = (rows, fuel, field) => {
  const s = rows.reduce((a,r) => { const n=parseInt(toEn(r[fuel][field])); return a+(isNaN(n)?0:n); },0);
  return s > 0 ? toBn(s) : "-";
};

/* ── Load external script ── */
const loadScript = (src) => new Promise((res,rej) => {
  if (document.querySelector(`script[src="${src}"]`)) { res(); return; }
  const s = document.createElement("script"); s.src=src; s.onload=res; s.onerror=rej; document.head.appendChild(s);
});

/* ══════════════════════════════════
   DOCX — B&W, Nikosh, correct layout
══════════════════════════════════ */
async function downloadDocx(dateStr, rows) {
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/docx/8.5.0/docx.umd.min.js");
  const {
    Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
    AlignmentType, WidthType, BorderStyle, ShadingType, VerticalAlign, PageOrientation
  } = window.docx;

  const FONT = "Nikosh";
  const bdr  = { style:BorderStyle.SINGLE, size:4, color:"000000" };
  const bdrN = { style:BorderStyle.NONE, size:0, color:"FFFFFF" }; // no border
  const borders  = { top:bdr,  bottom:bdr,  left:bdr,  right:bdr  };
  const bordersN = { top:bdrN, bottom:bdrN, left:bdrN, right:bdrN };

  // Page margins from original: top=1152, right=1296, bottom=1008, left=1728
  const PAGE_W = 15840 - 1728 - 1296; // content width in DXA = 12816

  const mkCell = (text, {rowSpan,colSpan,bold,sz=20,align="center",shade,noBorder,width}={}) =>
    new TableCell({
      borders: noBorder ? bordersN : borders,
      verticalAlign: VerticalAlign.CENTER,
      rowSpan, columnSpan: colSpan,
      shading: shade ? { fill:shade, type:ShadingType.CLEAR } : undefined,
      width: width ? { size:width, type:WidthType.DXA } : undefined,
      margins:{ top:50, bottom:50, left:80, right:80 },
      children:[new Paragraph({
        alignment: align==="left" ? AlignmentType.LEFT : AlignmentType.CENTER,
        children:[new TextRun({ text:String(text), font:FONT, size:sz, bold:!!bold })]
      })]
    });

  const totals = {};
  FUELS.forEach(f=>{totals[f]={};FIELDS.forEach(fi=>{totals[f][fi]=calcTotal(rows,f,fi);});});

  // Column widths — total must = PAGE_W = 12816
  // Serial:600, Upazila:900, Name:2400, then 9 data cols each ~1024 = 9216, total=600+900+2400+9216=13116
  // Adjust: serial=550, upazila=800, name=2200, each data=1029 → 550+800+2200+9*1029=550+800+2200+9261=12811 ≈ ok
  const S=550, U=800, N=2250;
  const D=Math.floor((PAGE_W-S-U-N)/9); // each data col
  const colWidths = [S, U, N, D,D,D, D,D,D, D,D,D];

  const mainTable = new Table({
    width:{ size:PAGE_W, type:WidthType.DXA },
    columnWidths: colWidths,
    rows:[
      // Header row 1
      new TableRow({ children:[
        mkCell("ক্রঃনং",           {rowSpan:2, shade:"CCCCCC", bold:true, sz:18, width:S}),
        mkCell("উপজেলা",           {rowSpan:2, shade:"CCCCCC", bold:true, sz:18, width:U}),
        mkCell("প্রতিষ্ঠানের নাম", {rowSpan:2, shade:"CCCCCC", bold:true, sz:18, width:N}),
        mkCell("ডিজেল",   {colSpan:3, shade:"AAAAAA", bold:true, sz:20, width:D*3}),
        mkCell("পেট্রোল", {colSpan:3, shade:"AAAAAA", bold:true, sz:20, width:D*3}),
        mkCell("অকটেন",   {colSpan:3, shade:"AAAAAA", bold:true, sz:20, width:D*3}),
      ]}),
      // Header row 2
      new TableRow({ children:[
        ...FUELS.flatMap(()=>FIELDS.map(fi=>mkCell(FIELD_LBL[fi], {shade:"CCCCCC", sz:16, width:D})))
      ]}),
      // Data rows
      ...STATIONS.map((s,i)=>new TableRow({ children:[
        mkCell(toBn(String(i+1).padStart(2,"0")), {sz:20, width:S}),
        mkCell(i===0?"জীবননগর":"", {sz:20, width:U}),
        new TableCell({ borders, width:{size:N,type:WidthType.DXA},
          margins:{top:50,bottom:50,left:80,right:80},
          children:[new Paragraph({ alignment:AlignmentType.LEFT,
            children:[new TextRun({text:s.name, font:FONT, size:18})] })]
        }),
        ...FUELS.flatMap(f=>FIELDS.map(fi=>mkCell(rows[i][f][fi]||"-", {sz:20, width:D})))
      ]})),
      // Total row
      new TableRow({ children:[
        new TableCell({ borders, columnSpan:3, width:{size:S+U+N,type:WidthType.DXA},
          shading:{fill:"AAAAAA",type:ShadingType.CLEAR}, margins:{top:50,bottom:50,left:80,right:80},
          children:[new Paragraph({alignment:AlignmentType.CENTER,
            children:[new TextRun({text:"সর্বমোট", font:FONT, size:20, bold:true})]})]
        }),
        ...FUELS.flatMap(f=>FIELDS.map(fi=>mkCell(totals[f][fi], {bold:true, sz:20, width:D})))
      ]})
    ]
  });

  // Signature table — 2 cols: left empty, right = "উপজেলা নির্বাহী অফিসার\nজীবননগর, চুয়াডাঙ্গা।"
  // Both columns center-aligned (as in original doc)
  const sigTable = new Table({
    width:{ size:PAGE_W, type:WidthType.DXA },
    columnWidths:[PAGE_W/2, PAGE_W/2],
    rows:[
      new TableRow({ children:[
        mkCell("", {noBorder:true, width:PAGE_W/2}),
        new TableCell({
          borders: bordersN,
          width:{size:PAGE_W/2, type:WidthType.DXA},
          margins:{top:200,bottom:50,left:80,right:80},
          children:[
            new Paragraph({ alignment:AlignmentType.CENTER,
              children:[new TextRun({text:"উপজেলা নির্বাহী অফিসার", font:FONT, size:22})]
            }),
            new Paragraph({ alignment:AlignmentType.CENTER,
              children:[new TextRun({text:"জীবননগর, চুয়াডাঙ্গা।", font:FONT, size:22})]
            }),
          ]
        }),
      ]})
    ]
  });

  const run  = (text, sz=26, bold=false) => new TextRun({text, font:FONT, size:sz, bold});
  const para = (children, align=AlignmentType.CENTER, after=120) =>
    new Paragraph({alignment:align, spacing:{after}, children});

  const doc = new Document({
    sections:[{
      properties:{ page:{
        size:{ width:12240, height:15840, orientation:PageOrientation.LANDSCAPE },
        margin:{ top:1152, right:1296, bottom:1008, left:1728 }
      }},
      children:[
        para([run("উপজেলা: জীবননগর", 28, true)],           AlignmentType.CENTER, 80),
        para([run("জ্বালানী তেলের দৈনিক রিপোর্ট", 26, true)], AlignmentType.CENTER, 80),
        para([run(`তারিখ: ${fmtDate(dateStr)}`, 24)],        AlignmentType.CENTER, 200),
        mainTable,
        new Paragraph({spacing:{after:0}, children:[]}),
        sigTable,
      ]
    }]
  });

  const blob = await Packer.toBlob(doc);
  const url  = URL.createObjectURL(blob);
  Object.assign(document.createElement("a"),{href:url,download:`fuel_report_${dateStr}.docx`}).click();
  URL.revokeObjectURL(url);
}

/* ══════════════════════════════════
   PDF — html2canvas render, Nikosh
══════════════════════════════════ */
async function downloadPdf(dateStr, rows) {
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js");
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js");
  const { jsPDF } = window.jspdf;
  const totals = {};
  FUELS.forEach(f=>{totals[f]={};FIELDS.forEach(fi=>{totals[f][fi]=calcTotal(rows,f,fi);});});

  const wrapper = document.createElement("div");
  wrapper.style.cssText = "position:fixed;left:-9999px;top:0;width:1200px;background:#fff;padding:28px 36px;font-family:'Nikosh',sans-serif;color:#000;";
  wrapper.innerHTML = `
    <div style="text-align:center;margin-bottom:6px;font-family:'Nikosh',sans-serif">
      <div style="font-size:20px;font-weight:800">উপজেলা: জীবননগর</div>
      <div style="font-size:17px;font-weight:700;margin-top:4px">জ্বালানী তেলের দৈনিক রিপোর্ট</div>
      <div style="font-size:14px;margin-top:4px">তারিখ: ${fmtDate(dateStr)}</div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:11.5px;margin-top:10px;font-family:'Nikosh',sans-serif">
      <thead>
        <tr>
          <th rowspan="2" style="border:1px solid #000;padding:5px 4px;background:#aaa;text-align:center;font-weight:700">ক্রঃনং</th>
          <th rowspan="2" style="border:1px solid #000;padding:5px 4px;background:#aaa;text-align:center;font-weight:700">উপজেলা</th>
          <th rowspan="2" style="border:1px solid #000;padding:5px 4px;background:#aaa;text-align:center;font-weight:700;min-width:170px">প্রতিষ্ঠানের নাম</th>
          ${FUELS.map(f=>`<th colspan="3" style="border:1px solid #000;padding:5px 4px;background:#888;text-align:center;font-weight:700;color:#fff">${FUEL_LBL[f]}</th>`).join("")}
        </tr>
        <tr>
          ${FUELS.map(()=>FIELDS.map(fi=>`<th style="border:1px solid #000;padding:4px 3px;background:#ccc;text-align:center;font-size:10px">${FIELD_LBL[fi]}</th>`).join("")).join("")}
        </tr>
      </thead>
      <tbody>
        ${STATIONS.map((s,i)=>`
          <tr>
            <td style="border:1px solid #000;padding:4px;text-align:center">${toBn(String(i+1).padStart(2,"0"))}</td>
            <td style="border:1px solid #000;padding:4px;text-align:center">${i===0?"জীবননগর":""}</td>
            <td style="border:1px solid #000;padding:4px;font-size:10.5px">${s.name}</td>
            ${FUELS.map(f=>FIELDS.map(fi=>`<td style="border:1px solid #000;padding:4px;text-align:center">${rows[i][f][fi]||"-"}</td>`).join("")).join("")}
          </tr>`).join("")}
        <tr>
          <td colspan="3" style="border:1px solid #000;padding:5px;text-align:center;font-weight:800;background:#aaa">সর্বমোট</td>
          ${FUELS.map(f=>FIELDS.map(fi=>`<td style="border:1px solid #000;padding:4px;text-align:center;font-weight:700;background:#ccc">${totals[f][fi]}</td>`).join("")).join("")}
        </tr>
      </tbody>
    </table>
    <table style="width:100%;border-collapse:collapse;margin-top:24px;font-family:'Nikosh',sans-serif">
      <tr>
        <td style="width:50%;border:none;padding:0"></td>
        <td style="width:50%;border:none;padding:10px 0 0;text-align:center;font-size:14px;line-height:2">
          উপজেলা নির্বাহী অফিসার<br/>জীবননগর, চুয়াডাঙ্গা।
        </td>
      </tr>
    </table>
  `;
  document.body.appendChild(wrapper);
  if (document.fonts?.ready) await document.fonts.ready;
  await new Promise(r=>setTimeout(r,400));
  const canvas = await window.html2canvas(wrapper, { scale:2, useCORS:true, backgroundColor:"#ffffff" });
  document.body.removeChild(wrapper);
  const pdf    = new jsPDF({ orientation:"landscape", unit:"mm", format:"a4" });
  const pW     = pdf.internal.pageSize.getWidth();
  const pH     = pdf.internal.pageSize.getHeight();
  const finalW = pW - 10;
  const finalH = (canvas.height / canvas.width) * finalW;
  pdf.addImage(canvas.toDataURL("image/png"), "PNG", 5, 5, finalW, Math.min(finalH, pH-10));
  pdf.save(`fuel_report_${dateStr}.pdf`);
}

/* ════════════════
   Main App
════════════════ */
export default function App() {
  const [view,setView]         = useState("entry");
  const [allData,setAllData]   = useState({});
  const [selDate,setSelDate]   = useState(todayStr());
  const [rows,setRows]         = useState(emptyData());
  const [loaded,setLoaded]     = useState(false);
  const [savedDates,setSaved]  = useState([]);
  const [histDate,setHistDate] = useState("");
  const [histRows,setHistRows] = useState(null);
  const [msg,setMsg]           = useState("");
  const [dlState,setDlState]   = useState("");

  useEffect(()=>{ loadAll().then(all=>{ setAllData(all); setSaved(Object.keys(all).sort().reverse()); setLoaded(true); }); },[]);

  useEffect(()=>{
    if(!loaded) return;
    if(allData[selDate]){ setRows(allData[selDate]); return; }
    const prev = Object.keys(allData).filter(d=>d<selDate).sort().reverse()[0];
    if(prev){
      setRows(allData[prev].map(r=>({
        stationId:r.stationId,
        diesel:{prev:r.diesel.closing,received:"",closing:""},
        petrol:{prev:r.petrol.closing,received:"",closing:""},
        octane:{prev:r.octane.closing,received:"",closing:""},
      })));
    } else { setRows(emptyData()); }
  },[selDate,loaded]);

  const setCell=(ri,f,fi,v)=>setRows(rs=>rs.map((r,i)=>i!==ri?r:{...r,[f]:{...r[f],[fi]:v}}));
  const flash=(m)=>{setMsg(m);setTimeout(()=>setMsg(""),2500);};

  const handleSave=async()=>{
    const updated={...allData,[selDate]:rows};
    setAllData(updated); setSaved(Object.keys(updated).sort().reverse());
    await saveAll(updated); flash("✓ সংরক্ষিত হয়েছে!");
  };

  const handleDl=async(type,date,rowsArr)=>{
    setDlState(date+"_"+type);
    try{
      if(type==="docx") await downloadDocx(date,rowsArr);
      else              await downloadPdf(date,rowsArr);
    } catch(e){ console.error(e); alert("ডাউনলোড ব্যর্থ: "+e.message); }
    setDlState("");
  };

  const deleteDate=async(d)=>{
    if(!window.confirm("এই তারিখের তথ্য মুছে ফেলবেন?")) return;
    const u={...allData}; delete u[d]; setAllData(u); setSaved(Object.keys(u).sort().reverse());
    await saveAll(u); if(histDate===d){setHistDate("");setHistRows(null);}
  };

  /* ── Cell styles ── */
  const TH  = { border:"1px solid #000", padding:"5px 4px", fontWeight:700, textAlign:"center", fontSize:12, color:"#000", background:"#ccc" };
  const THD = { ...TH, background:"#999", color:"#000" };
  const TD  = { border:"1px solid #000", padding:"3px 4px", verticalAlign:"middle", color:"#000", background:"#fff" };
  const TDG = { ...TD, background:"#ccc", fontWeight:700 };

  const DlBar=({date,rowsArr})=>(
    <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
      {[["docx","📄 DOCX"],["pdf","📕 PDF"]].map(([t,lbl])=>{
        const busy=dlState===date+"_"+t;
        return <button key={t} onClick={()=>handleDl(t,date,rowsArr)} disabled={!!dlState}
          style={{background:busy?"#888":"#222",color:"#fff",border:"none",padding:"7px 18px",cursor:busy?"not-allowed":"pointer",fontWeight:700,fontSize:13,fontFamily:"'Nikosh',sans-serif"}}>
          {busy?"⏳ তৈরি হচ্ছে...":lbl+" ডাউনলোড"}
        </button>;
      })}
    </div>
  );

  const ReportTable=({rowsArr,editable})=>(
    <div style={{overflowX:"auto"}}>
      <table style={{borderCollapse:"collapse",width:"100%",minWidth:980,background:"#fff"}}>
        <thead>
          <tr>
            <th rowSpan={2} style={TH}>ক্রঃনং</th>
            <th rowSpan={2} style={TH}>উপজেলা</th>
            <th rowSpan={2} style={{...TH,minWidth:160}}>প্রতিষ্ঠানের নাম</th>
            {FUELS.map(f=><th key={f} colSpan={3} style={THD}>{FUEL_LBL[f]}</th>)}
          </tr>
          <tr>
            {FUELS.map(f=>FIELDS.map((fi,hi)=>(
              <th key={f+hi} style={{...TH,fontSize:10}}>{FIELD_LBL[fi]}</th>
            )))}
          </tr>
        </thead>
        <tbody>
          {STATIONS.map((s,i)=>(
            <tr key={s.id}>
              <td style={{...TD,textAlign:"center",fontWeight:600}}>{toBn(String(i+1).padStart(2,"0"))}</td>
              <td style={{...TD,textAlign:"center"}}>{i===0?"জীবননগর":""}</td>
              <td style={{...TD,fontSize:11}}>{s.name}</td>
              {FUELS.map(f=>FIELDS.map(fi=>(
                <td key={f+fi} style={{...TD,padding:editable?1:3}}>
                  {fi==="prev"?(
                    <div style={{textAlign:"center",padding:"3px 5px",background:"#eee",color:"#000",fontWeight:600,fontSize:12}}>
                      {rowsArr[i][f][fi]||<span style={{color:"#aaa"}}>-</span>}
                    </div>
                  ):editable?(
                    <input value={rows[i][f][fi]} onChange={e=>setCell(i,f,fi,e.target.value)}
                      style={{width:"100%",border:fi==="closing"?"2px solid #000":"1px solid #888",padding:"3px 4px",textAlign:"center",fontSize:12,background:"#fff",boxSizing:"border-box",fontFamily:"'Nikosh',sans-serif",color:"#000"}}
                      placeholder="-"/>
                  ):(
                    <div style={{textAlign:"center",fontSize:12}}>{rowsArr[i][f][fi]||"-"}</div>
                  )}
                </td>
              )))}
            </tr>
          ))}
          <tr>
            <td colSpan={3} style={{...TDG,textAlign:"center"}}>সর্বমোট</td>
            {FUELS.map(f=>FIELDS.map(fi=>(
              <td key={f+fi} style={{...TDG,textAlign:"center"}}>{calcTotal(rowsArr,f,fi)}</td>
            )))}
          </tr>
        </tbody>
      </table>
    </div>
  );

  /* Signature: 2-column table, right cell centered */
  const Signature=()=>(
    <table style={{width:"100%",borderCollapse:"collapse",marginTop:20}}>
      <tbody>
        <tr>
          <td style={{width:"50%",border:"none",padding:0}}></td>
          <td style={{width:"50%",border:"none",textAlign:"center",fontSize:14,lineHeight:"2",color:"#000",fontFamily:"'Nikosh',sans-serif",paddingTop:8}}>
            উপজেলা নির্বাহী অফিসার<br/>জীবননগর, চুয়াডাঙ্গা।
          </td>
        </tr>
      </tbody>
    </table>
  );

  const ReportHeader=({date})=>(
    <div style={{textAlign:"center",padding:"10px 0 6px",borderBottom:"2px solid #000",marginBottom:8}}>
      <div style={{fontWeight:800,fontSize:17}}>উপজেলা: জীবননগর</div>
      <div style={{fontWeight:700,fontSize:15,marginTop:3}}>জ্বালানী তেলের দৈনিক রিপোর্ট</div>
      <div style={{fontSize:13,marginTop:3}}>তারিখ: {fmtDate(date)}</div>
    </div>
  );

  if(!loaded) return <div style={{padding:40,textAlign:"center",fontFamily:"'Nikosh',sans-serif"}}>লোড হচ্ছে...</div>;

  return (
    <div style={{fontFamily:"'Nikosh',sans-serif",minHeight:"100vh",background:"#f0f0f0",color:"#000"}}>

      {/* Topbar */}
      <div style={{background:"#111",color:"#fff",padding:"12px 20px",display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:10}}>
        <div>
          <div style={{fontWeight:800,fontSize:18}}>⛽ জ্বালানী তেলের দৈনিক রিপোর্ট</div>
          <div style={{fontSize:12,opacity:.7}}>উপজেলা: জীবননগর, চুয়াডাঙ্গা</div>
        </div>
        <div style={{display:"flex",gap:8}}>
          {[["entry","📝 তথ্য প্রবেশ"],["history","📅 তারিখ ভিত্তিক"]].map(([v,l])=>(
            <button key={v} onClick={()=>setView(v)}
              style={{background:view===v?"#fff":"transparent",color:view===v?"#111":"#fff",border:view===v?"none":"1px solid rgba(255,255,255,.4)",padding:"7px 14px",cursor:"pointer",fontWeight:700,fontSize:13,fontFamily:"'Nikosh',sans-serif"}}>
              {l}
            </button>
          ))}
        </div>
      </div>

      {/* Entry */}
      {view==="entry"&&(
        <div style={{padding:"16px"}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12,flexWrap:"wrap",background:"#fff",padding:"10px 14px",border:"1px solid #ccc"}}>
            <label style={{fontWeight:700,fontSize:14}}>📅 তারিখ:</label>
            <input type="date" value={selDate} onChange={e=>setSelDate(e.target.value)}
              style={{padding:"6px 10px",border:"1px solid #888",fontSize:14,fontFamily:"'Nikosh',sans-serif"}}/>
            <div style={{fontWeight:600,fontSize:14}}>{fmtDate(selDate)}</div>
            <button onClick={handleSave}
              style={{background:"#222",color:"#fff",border:"none",padding:"7px 18px",fontSize:13,cursor:"pointer",fontWeight:700,fontFamily:"'Nikosh',sans-serif"}}>
              💾 সংরক্ষণ
            </button>
            {msg&&<span style={{fontWeight:700,fontSize:13,border:"1px solid #000",padding:"3px 10px"}}>{msg}</span>}
          </div>

          <div style={{background:"#fff",padding:"10px 14px",border:"1px solid #ccc",marginBottom:8}}>
            <ReportHeader date={selDate}/>
            <ReportTable rowsArr={rows} editable={true}/>
            <Signature/>
          </div>

          <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"center",marginTop:8}}>
            <DlBar date={selDate} rowsArr={allData[selDate]||rows}/>
            <span style={{fontSize:12,color:"#555"}}>💡 <b>পূর্বের মজুদ</b> আগের দিন থেকে স্বয়ংক্রিয়। <b>গাঢ় বর্ডার</b> = সমাপনী মজুদ।</span>
          </div>
        </div>
      )}

      {/* History */}
      {view==="history"&&(
        <div style={{padding:"16px"}}>
          <div style={{fontWeight:700,fontSize:16,marginBottom:10,borderBottom:"2px solid #000",paddingBottom:6}}>📅 সংরক্ষিত তারিখসমূহ</div>
          {savedDates.length===0&&<div style={{color:"#555"}}>কোনো তথ্য সংরক্ষিত নেই।</div>}
          <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:16}}>
            {savedDates.map(d=>(
              <div key={d} onClick={()=>{setHistDate(d);setHistRows(allData[d]);}}
                style={{background:histDate===d?"#222":"#fff",color:histDate===d?"#fff":"#000",border:"1px solid #000",padding:"5px 12px",cursor:"pointer",display:"flex",alignItems:"center",gap:8,fontWeight:600,fontSize:13}}>
                {fmtDate(d)}
                <span onClick={e=>{e.stopPropagation();deleteDate(d);}}
                  style={{fontWeight:800,fontSize:15,marginLeft:2,cursor:"pointer",color:histDate===d?"#ccc":"#000"}}>×</span>
              </div>
            ))}
          </div>

          {histRows&&(
            <div style={{background:"#fff",padding:"10px 14px",border:"1px solid #ccc"}}>
              <ReportHeader date={histDate}/>
              <ReportTable rowsArr={histRows} editable={false}/>
              <Signature/>
              <div style={{marginTop:12}}>
                <DlBar date={histDate} rowsArr={histRows}/>
              </div>
            </div>
          )}
        </div>
      )}

      <style>{`
        @import url('https://fonts.maateen.me/nikosh/font.css');
        * { box-sizing:border-box; }
        body, input, button, th, td { font-family:'Nikosh',sans-serif !important; }
        input:focus { outline:2px solid #000; }
      `}</style>
    </div>
  );
}
